+/** Milliseconds to wait before attempt `attempt`: 1s, 2s, 4s, 8s, 16s. */
+export function backoff(attempt: number): number {
+  return 1000 * 2 ** (attempt - 1);
+}
+
+/** A status worth trying again: the server's fault, or ours for asking too soon. */
+export function isRetryable(status: number): boolean {
+  return status >= 500 || status === 429 || status === 408;
+}
+
+export const RETRY_AFTER_CAP_MS = 60_000;
+
+export function retryAfter(header: string | null): number | null {
+  const seconds = header ? Number(header) : NaN;
+  return Number.isFinite(seconds) ? Math.min(seconds * 1000, RETRY_AFTER_CAP_MS) : null;
+}

